<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { api, ApiError } from '../api'
import { useAuth } from '../auth'
type Config={enabled:boolean;provider_name:string;base_url:string;model:string;provider_options:Record<string,unknown>;currency:string;input_price_per_million:string;cached_input_price_per_million:string;output_price_per_million:string;monthly_budget:string;monthly_token_limit:number;daily_call_limit:number;user_daily_call_limit:number;admin_daily_call_limit:number;max_output_tokens:number;max_tool_rounds:number;revision:number;key_configured:boolean;discovered_models:string[]}
type Usage={charged_cost:string;currency:string;charged_tokens:number;prompt_tokens:number;completion_tokens:number;cache_hit_tokens:number;cache_miss_tokens:number;provider_calls:number;estimated:boolean}
type ModelInfo={id:string;name?:string;owned_by?:string;context_window?:number;max_output_tokens?:number;input_modalities?:string[];output_modalities?:string[];effort?:{supported_levels:string[];default_level?:string};api_capabilities?:{anthropic_messages:{system_prompt_update:string}}}
const modelDetails=ref<ModelInfo[]>([])
const preset=ref('generic')
type Outcome={status:string;request_id:string;answer?:string|null;models?:ModelInfo[];error?:{code:string};usage?:Usage}
type RequestAccount={request_id:string;purpose:string;status:string;owner_user_id?:number;created_at:string;lease_expires_at?:string;charged_cost:string;charged_tokens:number;usage_estimated:boolean;reconciled:boolean;recovery?:{at?:string;unknown_calls?:number};dispatched_calls:number}
type Reconciliation={reconciliation_id:string;reason:string;evidence:string;actual_prompt_tokens:number;actual_completion_tokens:number;actual_cache_hit_tokens:number;actual_cost:string}
const recent=ref<RequestAccount[]>([]),testResult=ref<Outcome>(),reconcileTarget=ref<string>(),reconcileDraft=ref<Reconciliation>(),reconcileSnapshot=ref<Reconciliation>(),reconcileUncertain=ref(false),reconcileConsent=ref(false)
const setupStage=computed(()=>!form.value?.base_url||!form.value.key_configured?'等待保存连接及密钥':!form.value.discovered_models.length?'连接已保存，等待发现模型':!form.value.model?'模型已发现，等待选择并保存':testResult.value?.status!=='completed'?'模型已保存，可先通用测试，再启用':form.value.enabled?'研究助手已启用；通用测试通过':'通用测试通过，可启用研究助手')
const discoveryReason=computed(()=>!auth.isAdmin?'仅管理员可发现模型':busy.value?'请求处理中，请等待':dirty.value?'请先保存连接或其他修改':!form.value?.base_url?'请先选择服务商并保存接口地址':!form.value.key_configured?'请先填写并保存 API Key':'')
const testReason=computed(()=>!auth.isAdmin?'仅管理员可测试连接':busy.value?'请求处理中，请等待':testUncertain.value?'':dirty.value?'请先保存修改（输入密钥不等于服务器已保存）':!form.value?.key_configured?'请先保存 API Key':!form.value.base_url?'请先保存接口地址':!form.value.model?'请先发现、选择并保存模型':!testConsent.value?'请勾选允许发送通用问候；不发送实验记录':'')
const enableReason=computed(()=>busy.value?'请求处理中，请等待':providerChanged.value?'请先保存连接与密钥，再重新发现模型':!form.value?.key_configured?'请先保存 API Key':!form.value.model||!modelOptions.value.includes(form.value.model)?'请先发现并选择模型':'')
const selectedMetadata=computed(()=>modelDetails.value.find(m=>m.id===form.value?.model))
function choosePreset(){if(!form.value)return;stageConnection();key.value='';clearKey.value=false;modelDetails.value=[];form.value.base_url=preset.value==='deepseek'?'https://api.deepseek.com':'';form.value.provider_name=preset.value==='deepseek'?'DeepSeek':'OpenAI-compatible';form.value.provider_options=preset.value==='deepseek'?{thinking:{type:'disabled'}}:{}}

const remaining=computed(()=>usage.value?{cost:Math.max(0,Number(usage.value.monthly_budget)-Number(usage.value.charged_cost)-Number(usage.value.reserved_cost)).toFixed(8),tokens:Math.max(0,Number(usage.value.monthly_token_limit)-Number(usage.value.charged_tokens)-Number(usage.value.reserved_tokens))}:null)
const reserveEstimate=computed(()=>{const f=form.value;if(!f)return null;const calls=f.max_tool_rounds+1,one=(60000*Number(f.input_price_per_million)+f.max_output_tokens*Number(f.output_price_per_million))/1000000;return {tokens:calls*(60000+f.max_output_tokens),cost:(Math.ceil(one*1e8)/1e8*calls).toFixed(8),testCost:(Math.ceil(one*1e8)/1e8).toFixed(8)}})
function eligible(r:RequestAccount){return r.status!=='pending'&&r.usage_estimated&&!r.reconciled}
function stateLabel(r:RequestAccount){return r.reconciled?'已核对账务':r.recovery?'中断已恢复':r.status==='pending'?'处理中':r.status==='completed'?'已完成':'已终结（失败）'}
const auth=useAuth(),form=ref<Config>(),baseline=ref(''),key=ref(''),clearKey=ref(false),busy=ref(false),message=ref(''),error=ref(''),usage=ref<Record<string,any>>(),testConsent=ref(false),testId=ref<string>(),testUncertain=ref(false)
let epoch=0
const dirty=computed(()=>!!form.value&&(JSON.stringify(form.value)!==baseline.value||!!key.value||clearKey.value))
const providerChanged=computed(()=>{if(!form.value||!baseline.value)return false;const old=JSON.parse(baseline.value);return form.value.base_url!==old.base_url||!!key.value||clearKey.value})
const modelOptions=computed(()=>providerChanged.value?[]:form.value?.discovered_models??[])
const deepSeekEndpoint=computed(()=>{try{return new URL(form.value?.base_url??'').hostname.toLowerCase()==='api.deepseek.com'}catch{return false}})
function requireNonthinking(){if(deepSeekEndpoint.value&&form.value)form.value.provider_options={thinking:{type:'disabled'}}}
watch(()=>form.value?.base_url,requireNonthinking)
const prices=[['input_price_per_million','输入价格（每百万 Token）'],['cached_input_price_per_million','缓存命中输入价格'],['output_price_per_million','输出价格（每百万 Token）'],['monthly_budget','每月金额预算']] as const
const caps=[['monthly_token_limit','每月 Token 上限',1000,1000000000],['daily_call_limit','全站每日服务商调用上限',1,100000],['user_daily_call_limit','普通用户每日调用上限',1,10000],['admin_daily_call_limit','管理员每日调用上限',1,10000],['max_output_tokens','每次最大输出 Token',64,4096],['max_tool_rounds','最大工具轮数',1,4]] as const
function accept(data:Config){form.value=data;baseline.value=JSON.stringify(data);key.value='';clearKey.value=false;preset.value=(()=>{try{return new URL(data.base_url).hostname==='api.deepseek.com'?'deepseek':'generic'}catch{return 'generic'}})();requireNonthinking()}
function providerFailure(code?:string){return ({provider_auth_failed:'服务商拒绝 API Key，请核对密钥后重新保存。',provider_insufficient_balance:'服务商余额不足，请在服务商账户核对。',provider_permission_denied:'当前密钥没有所选模型或接口权限。',provider_rate_limited:'服务商限流，请稍后重试。',endpoint_not_public:'接口未通过公网地址校验，未发送密钥。',provider_parameter_invalid:'服务商拒绝参数，请核对模型与非思考设置。'} as Record<string,string>)[code??'']??'请求失败，请检查 API Key、余额、模型权限和预算；费用可能未知。'}
function failure(e:unknown){return e instanceof ApiError&&e.status===409?'配置已变化或预算低于已计账及预留用量，请重新加载核对。':e instanceof ApiError&&e.status===429?'已达到预算、Token 或每日调用上限。':e instanceof ApiError&&e.status===422?'配置未通过校验，请检查 HTTPS 地址、模型发现、DeepSeek 关闭 thinking 设置和数字范围。':'AI 服务暂时不可用，请检查服务或配置。'}
async function load(){if(!auth.isAdmin)return;const ticket=epoch;busy.value=true;error.value='';try{const {data}=await api<Config>('/ai/config');if(ticket!==epoch)return;accept(data);await loadUsage(ticket);await loadRequests(ticket)}catch(e){if(ticket===epoch)error.value=failure(e)}finally{if(ticket===epoch)busy.value=false}}
async function loadUsage(ticket=epoch){try{const {data}=await api<Record<string,any>>('/ai/usage');if(ticket===epoch)usage.value=data}catch{if(ticket===epoch)error.value='无法读取 AI 用量。'}}
async function reload(){if(dirty.value&&!await discard())return;await load()}
async function discard(){try{await ElMessageBox.confirm('AI 设置有未保存修改，是否放弃？输入的密钥会清空。','未保存的修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function save(){if(!form.value||busy.value)return;error.value='';message.value='';const f=form.value
 if(providerChanged.value&&(f.enabled||f.model)){error.value='连接或密钥已改变，请先停用并清空模型，保存连接后重新发现模型。';return}
 if(f.enabled&&(!f.model||!modelOptions.value.includes(f.model))){error.value='请先发现并选择模型，再启用。';return}
 if(deepSeekEndpoint.value&&JSON.stringify(f.provider_options)!==JSON.stringify({thinking:{type:'disabled'}})){error.value='DeepSeek 官方接口必须显式关闭 thinking，请重新加载并保存设置。';return}
 const decimal=/^(?:0|[1-9]\d*)(?:\.\d{1,8})?$/
 if(prices.some(([k])=>!decimal.test(String(f[k]))||!Number.isFinite(Number(f[k]))||Number(f[k])>(k==='monthly_budget'?1000000:10000)||Number(f[k])<(k==='cached_input_price_per_million'?0:0.00000001))){error.value='输入及输出价格须大于 0 且不超过 10000；缓存价格可为 0，月预算须大于 0 且不超过 1000000。金额最多八位小数，不使用科学计数法。';return}
 if(caps.some(([k,,min,max])=>!Number.isInteger(f[k])||f[k]<min||f[k]>max)){error.value='调用边界须填写范围内的整数，请检查每个数字的最小值和最大值。';return}
 const retainTest=!!baseline.value&&JSON.stringify({...JSON.parse(baseline.value),enabled:f.enabled})===JSON.stringify(f)
 const ticket=epoch;busy.value=true
 const fields=['enabled','provider_name','base_url','model','provider_options','currency',...prices.map(x=>x[0]),...caps.map(x=>x[0]),'revision']
 const body:Record<string,unknown>=Object.fromEntries(fields.map(k=>[k,(f as any)[k]]));body.clear_api_key=clearKey.value;if(key.value)body.api_key=key.value
 try{const {data}=await api<Config>('/ai/config',{method:'PUT',body});if(ticket!==epoch)return;accept(data);if(!retainTest)testResult.value=undefined;message.value='设置已保存。';await loadUsage(ticket)}catch(e){if(ticket===epoch)error.value=failure(e)}finally{delete body.api_key;key.value='';if(ticket===epoch)busy.value=false}
}
function stageConnection(){testResult.value=undefined;testConsent.value=false;modelDetails.value=[];if(!form.value)return;form.value.enabled=false;form.value.model=''}
async function discover(){if(discoveryReason.value)return;const ticket=epoch;busy.value=true;message.value='';error.value='';try{const {data}=await api<Outcome>('/ai/models');if(ticket!==epoch)return;if(data.status!=='completed'){error.value=providerFailure(data.error?.code);return}const config=await api<Config>('/ai/config');if(ticket!==epoch)return;accept(config.data);modelDetails.value=data.models??[];message.value=`发现 ${data.models?.length??0} 个模型。请选择后保存，先测试再启用。`;await loadUsage(ticket)}catch(e){if(ticket===epoch)error.value=failure(e)}finally{if(ticket===epoch)busy.value=false}}
async function loadRequests(ticket=epoch){if(!auth.isAdmin)return;try{const {data}=await api<{requests:RequestAccount[]}>('/ai/requests');if(ticket===epoch)recent.value=data.requests}catch{if(ticket===epoch)error.value='无法读取最近请求，请刷新重试。'}}
async function recover(){if(busy.value||!auth.isAdmin)return;const ticket=epoch;busy.value=true;error.value='';try{const {data}=await api<{recovered_count:number}>('/ai/recover',{method:'POST'});if(ticket!==epoch)return;message.value=`已恢复 ${data.recovered_count} 个过期请求。仅释放未使用预留，未知费用保守保留；未重新调用模型。`;await loadRequests(ticket);await loadUsage(ticket)}catch(e){if(ticket===epoch)error.value=failure(e)}finally{if(ticket===epoch)busy.value=false}}
function beginReconcile(r:RequestAccount){if(reconcileSnapshot.value||!eligible(r))return;reconcileTarget.value=r.request_id;reconcileConsent.value=false;reconcileDraft.value={reconciliation_id:crypto.randomUUID(),reason:'',evidence:'',actual_prompt_tokens:0,actual_completion_tokens:0,actual_cache_hit_tokens:0,actual_cost:'0'}}
async function reconcile(){if(busy.value||!auth.isAdmin||!reconcileTarget.value||!reconcileDraft.value||!reconcileConsent.value)return;const draft=reconcileSnapshot.value??reconcileDraft.value
 if(draft.reason.trim().length<10||draft.evidence.trim().length<10||draft.reason.length>1000||draft.evidence.length>2000||!/^((0|[1-9]\d*)(\.\d{1,8})?)$/.test(draft.actual_cost)||Number(draft.actual_cost)>1000000||[draft.actual_prompt_tokens,draft.actual_completion_tokens,draft.actual_cache_hit_tokens].some(n=>!Number.isInteger(n)||n<0||n>1000000000)||draft.actual_cache_hit_tokens>draft.actual_prompt_tokens){error.value='请填写至少 10 字的原因和账单证据，Token 须为 0 至 1000000000 的整数，缓存命中不能超过输入，金额为 0 至 1000000 且最多八位小数。';return}
 const ticket=epoch;reconcileSnapshot.value={...draft};busy.value=true;error.value=''
 try{await api<RequestAccount>(`/ai/requests/${reconcileTarget.value}/reconcile`,{method:'POST',body:reconcileSnapshot.value});if(ticket!==epoch)return;message.value='账务已核对。按凭证调整本地账本，保留原估算与审计记录；未再次调用模型。';reconcileTarget.value=undefined;reconcileDraft.value=undefined;reconcileSnapshot.value=undefined;reconcileUncertain.value=false;reconcileConsent.value=false;await loadRequests(ticket);await loadUsage(ticket)}catch(e){if(ticket!==epoch)return;reconcileUncertain.value=!(e instanceof ApiError&&e.status>=400&&e.status<500);if(!reconcileUncertain.value)reconcileSnapshot.value=undefined;error.value=reconcileUncertain.value?'核对响应中断，提交状态未知。已锁定原 UUID 和凭证；重试只重放同一笔账务核对，不调用模型。':failure(e)}finally{if(ticket===epoch)busy.value=false}}
async function test(){if(testReason.value)return;const ticket=epoch;busy.value=true;message.value='';error.value='';testId.value??=crypto.randomUUID();try{
 if(testUncertain.value){try{const {data:account}=await api<RequestAccount>(`/ai/requests/${testId.value}`);if(ticket!==epoch)return;if(account.status==='pending'){message.value='测试仍在处理，请使用原 ID 查询。';return}if(account.recovery||account.status==='failed'){testUncertain.value=false;testResult.value={status:'failed',request_id:testId.value};testId.value=undefined;error.value=account.recovery?'测试中断已恢复，未重新调用模型；请在最近请求核对未知费用。':'原测试已终结，请在最近请求查看费用。';await loadRequests(ticket);await loadUsage(ticket);return}}catch(e){if(!(e instanceof ApiError&&e.status===404))throw e}}
 const {data}=await api<Outcome>('/ai/test',{method:'POST',body:{request_id:testId.value}});if(ticket!==epoch)return;testResult.value=data;testUncertain.value=data.status==='pending';message.value=data.status==='completed'?`连接测试完成，本地估算 ${data.usage?.charged_cost??'0'} ${data.usage?.currency??''}。通用回复已收到；只读工具协议仍需实际查询验证。`:data.status==='pending'?'测试仍在处理，请使用原 ID 查询。':'';if(data.status==='failed')error.value=providerFailure(data.error?.code);if(data.status!=='pending')testId.value=undefined;await loadUsage(ticket);await loadRequests(ticket)
 }catch(e){if(ticket!==epoch)return;testUncertain.value=!(e instanceof ApiError&&e.status>=400&&e.status<500);error.value=testUncertain.value?'连接中断，计费状态未知。再次点击仅查询原请求，不自动创建新测试。':failure(e);if(!testUncertain.value)testId.value=undefined}finally{if(ticket===epoch)busy.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||reconcileSnapshot.value||testUncertain.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>{if(!auth.user)return true;if(reconcileSnapshot.value||testUncertain.value){error.value='原请求或账务核对结果尚未确认，请先使用原 ID 查询或重试核对后离开，以保留凭证。';return false}if(busy.value){error.value='请求处理中，请等待结果后离开。';return false}if(dirty.value&&!await discard())return false;key.value='';return true})
watch(()=>[auth.sessionEpoch,auth.user?.user_id,auth.user?.role],()=>{epoch++;busy.value=false;key.value='';clearKey.value=false;form.value=undefined;usage.value=undefined;testId.value=undefined;testConsent.value=false;testUncertain.value=false;testResult.value=undefined;recent.value=[];reconcileDraft.value=undefined;reconcileTarget.value=undefined;reconcileSnapshot.value=undefined;reconcileUncertain.value=false;reconcileConsent.value=false})
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{epoch++;key.value='';window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
 <div class="ai-settings">
  <div class="page-heading"><div><h1>AI 设置</h1><p>管理员配置模型连接与用量边界。研究助手只读，不修改科学记录。</p></div><el-button :disabled="busy" @click="reload">重新加载</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon role="alert"/>
  <el-alert v-if="message" :title="message" type="success" :closable="false" show-icon role="status"/>
  <div v-if="!form" class="panel empty-state">{{busy?'正在读取配置…':'未能读取配置，请重新加载。'}}</div>
  <template v-else>
   <section class="panel ai-setup" aria-label="连接准备状态"><strong>{{dirty?'配置有未保存修改':setupStage}}</strong><p>选择服务商 → 保存密钥 → 发现模型 → 选择并保存模型 → 通用测试 → 启用助手</p><p>{{form.key_configured?'密钥已保存（服务器仅返回已保存标记）':'尚未保存密钥'}}；{{form.discovered_models.length?'已有模型发现结果':'尚无模型发现结果'}}；{{testResult?.status==='completed'?'本页已收到通用测试回复':'本页尚无实时模型回复证据'}}。</p></section>
   <form class="panel ai-config" @submit.prevent="save"><fieldset :disabled="busy"><legend>模型连接</legend><p class="ai-help">选择服务商并保存连接和密钥，再发现、选择并保存模型；可在停用状态下先测试，最后启用。发现模型会连接服务商并占用每日调用次数，不发送实验记录。</p>
    <div class="form-grid"><label>服务商预设<select v-model="preset" aria-label="服务商预设" @change="choosePreset"><option value="deepseek">DeepSeek 官方</option><option value="generic">其他兼容服务商（高级）</option></select><span class="ai-help">DeepSeek 官方 HTTPS 地址自动填写，模型由当前密钥发现。<a href="https://api-docs.deepseek.com/api/list-models" target="_blank" rel="noopener noreferrer">官方模型文档</a></span></label><label>服务商名称<input v-model="form.provider_name" maxlength="64" required/></label><label>HTTPS 接口地址<input v-model="form.base_url" type="url" :readonly="preset==='deepseek'" placeholder="https://服务商地址/v1" @input="stageConnection"/></label>
    <label>新 API Key（只写）<input v-model="key" type="password" autocomplete="new-password" maxlength="512" :disabled="clearKey" @input="stageConnection"/><span class="ai-help">{{form.key_configured?'服务器已保存密钥；地址不变时留空保留，修改地址须填写新密钥，否则清除旧密钥。':'尚未保存密钥。'}} 保存尝试后和离开页面时清空输入，不在浏览器持久保存。</span></label>
    <div><label class="ai-checkbox"><input v-model="clearKey" type="checkbox" @change="key='';stageConnection()"/>清除服务器密钥</label><button type="button" class="ai-text-button" @click="stageConnection">停用并清空模型以修改连接</button><p class="ai-help">兼容 OpenAI 接口；地址、价格和模型均由管理员确认。</p></div>
    <label>已发现的模型<select aria-label="已发现的模型" v-model="form.model" :disabled="providerChanged"><option value="">请选择模型</option><option v-for="m in modelOptions" :key="m" :value="m">{{modelDetails.find(info=>info.id===m)?.name??m}} · {{m}}</option></select></label>
    <div class="ai-enable"><label class="ai-checkbox"><input v-model="form.enabled" type="checkbox" :disabled="!!enableReason" :title="enableReason"/>启用研究助手</label><p v-if="enableReason" class="ai-help" role="status">启用不可用：{{enableReason}}</p><label class="ai-checkbox"><input type="checkbox" :disabled="deepSeekEndpoint" :checked="Object.keys(form.provider_options).length>0" @change="form.provider_options=($event.target as HTMLInputElement).checked?{thinking:{type:'disabled'}}:{}"/>显式关闭 thinking（服务商支持时）</label><p v-if="deepSeekEndpoint" class="ai-help" role="status">当前地址为 DeepSeek 官方 api.deepseek.com：已自动选择并锁定关闭 thinking。本助手使用非思考工具流程；官方默认开启 thinking，与必需工具调用不兼容。请保存后再测试；通用问候成功不代表真实工具协议已验证。</p><p v-else class="ai-help">其他兼容服务商保持其原设置；仅在该服务商支持 thinking 参数时选择关闭。</p></div></div>
    <div class="ai-settings-actions"><el-button :disabled="!!discoveryReason" :title="discoveryReason" @click="discover">发现模型</el-button><span class="ai-help">{{discoveryReason||'发现结果来自当前服务商，不预设模型。'}}</span></div>
    <div v-if="form.model" class="ai-help" data-testid="model-metadata"><p>模型：{{selectedMetadata?.name??form.model}}；名称{{selectedMetadata?.name?'由 GET /models 返回':'未知（接口未返回或本页尚未重新发现）'}}。上下文：{{selectedMetadata?.context_window??'未知'}}；最大输出：{{selectedMetadata?.max_output_tokens??'未知'}}。</p><p>输入：{{selectedMetadata?.input_modalities?.join('、')??'未知'}}；输出：{{selectedMetadata?.output_modalities?.join('、')??'未知'}}；思考级别：{{selectedMetadata?.effort?.supported_levels.join('、')??'未知'}}。协议能力：{{selectedMetadata?.api_capabilities?JSON.stringify(selectedMetadata.api_capabilities):'未知'}}。这些是服务商声明，通用测试不验证科研工具能力。</p></div>
   </fieldset>
   <fieldset :disabled="busy"><legend>价格与预算</legend><p class="ai-help">价格为管理员填写的每百万 Token 估算值。请核对服务商当前价格（含高峰、缓存命中及输出价格），本地账本不是实际账单，也不声称价格实时准确。</p><div class="form-grid"><label>记账币种<input v-model="form.currency" maxlength="3" pattern="[A-Z]{3}" required placeholder="USD"/></label><label v-for="[name,label] in prices" :key="name">{{label}}<input v-model="form[name]" inputmode="decimal" required pattern="(?:0|[1-9][0-9]*)(?:\.[0-9]{1,8})?"/></label></div>
   </fieldset>
   <fieldset :disabled="busy"><legend>调用边界</legend><div class="form-grid"><label v-for="[name,label,min,max] in caps" :key="name">{{label}}<input v-model.number="form[name]" type="number" :min="min" :max="max" step="1" required/></label></div><p v-if="reserveEstimate" class="ai-help">按当前表单预估：一轮提问预留 {{reserveEstimate.tokens}} Token / {{reserveEstimate.cost}} {{form.currency}}；通用测试预留 {{60000+form.max_output_tokens}} Token / {{reserveEstimate.testCost}} {{form.currency}}。保存后生效，最终由服务器检查额度。</p><p class="ai-help">一次提问可触发多次服务商调用（最多工具轮数 + 1），每日上限按服务商调用计数。请求前保守预留预算；断连或计费未知时可能保留预留或按最坏情况记账。每次网络请求约 25 秒超时，整轮约 120 秒限制；非管理员不可修改这些边界。只读工具不读取原始文件内容。</p></fieldset>
   <div class="ai-save"><span>{{dirty?'有未保存修改':'配置已保存'}}</span><el-button type="primary" native-type="submit" :disabled="busy||!dirty">保存设置</el-button></div>
   </form>
   <section class="panel ai-test"><h2>连接测试</h2><label class="ai-checkbox"><input v-model="testConsent" type="checkbox" :disabled="busy"/>允许发送通用问候给已配置模型服务（不含实验数据，计入预算）</label><el-button :disabled="!!testReason" :title="testReason" @click="test">{{testUncertain?'使用原 ID 查询测试结果':'发送通用测试'}}</el-button><p class="ai-help" role="status" data-testid="test-disabled-reason">{{testReason||'可在助手停用时测试；仅发送通用问候，不读取实验记录。'}}</p><p v-if="testId" class="ai-help">原请求 ID：{{testId}}</p><div v-if="testResult" class="ai-test-result"><p>请求 ID：{{testResult.request_id}}</p><p v-if="testResult.answer" class="ai-plain">{{testResult.answer}}</p><p v-if="testResult.usage">输入 {{testResult.usage.prompt_tokens}} / 输出 {{testResult.usage.completion_tokens}} Token；缓存命中 {{testResult.usage.cache_hit_tokens}} / 未命中 {{testResult.usage.cache_miss_tokens}}；服务商调用 {{testResult.usage.provider_calls}} 次；{{testResult.usage.estimated?'保守估算（费用未知）':'按返回用量估算'}} {{testResult.usage.charged_cost}} {{testResult.usage.currency}}。</p></div></section>
   <section class="panel ai-usage"><div class="ai-usage-heading"><h2>本月全站用量</h2><el-button :disabled="busy" @click="loadUsage()">刷新用量</el-button></div><template v-if="usage"><p>{{usage.period}} · {{usage.currency}} · 全部用户</p><p v-if="remaining">扣除已记账及预留后剩余 {{remaining.cost}} {{usage.currency}} / {{remaining.tokens}} Token。</p><dl><div v-for="[name,label] in [['charged_cost','已记账估算金额'],['reserved_cost','预留金额'],['monthly_budget','月金额预算'],['charged_tokens','已记账 Token'],['reserved_tokens','预留 Token'],['monthly_token_limit','月 Token 上限'],['prompt_tokens','输入 Token'],['completion_tokens','输出 Token'],['provider_calls','服务商调用'],['cache_hit_tokens','缓存命中 Token'],['cache_miss_tokens','缓存未命中 Token'],['request_count','请求数'],['pending_requests','待处理请求'],['estimated_requests','保守估算请求']]" :key="name"><dt>{{label}}</dt><dd>{{usage[name]}}</dd></div></dl></template><p v-else>用量暂不可用。</p></section>
   <section class="panel ai-recovery"><div class="ai-usage-heading"><h2>最近请求与恢复</h2><div><el-button :disabled="busy" @click="loadRequests()">刷新请求</el-button><el-button :disabled="busy" @click="recover">恢复过期请求</el-button></div></div><p class="ai-help">最近 100 条全站请求。恢复只处理过期执行租约，释放未使用预留；已发送但未获用量的费用仍保守记账。恢复及核对均不重新调用模型。</p><p v-if="!recent.length">暂无请求记录。</p>
    <article v-for="r in recent" :key="r.request_id" class="ai-request"><strong>{{stateLabel(r)}} · {{r.purpose}} <span v-if="r.owner_user_id">· 用户 #{{r.owner_user_id}}</span></strong><p>请求 ID：{{r.request_id}}</p><p>创建 {{r.created_at}}；执行期限 {{r.lease_expires_at??'未提供'}}；已发送 {{r.dispatched_calls}} 次</p><p>{{r.usage_estimated?'费用未知，保守记账':'已记录用量'}}：{{r.charged_cost}}（原请求币种） / {{r.charged_tokens}} Token <span v-if="r.recovery">；已恢复 {{r.recovery.at}}，未知调用 {{r.recovery.unknown_calls??0}} 次</span></p><el-button v-if="eligible(r)" :disabled="busy||!!reconcileSnapshot" @click="beginReconcile(r)">凭服务商账单核对</el-button></article>
    <form v-if="reconcileDraft&&reconcileTarget" class="ai-reconcile" @submit.prevent="reconcile"><h3>核对账务</h3><p>请求 {{reconcileTarget}}</p><p>核对 UUID：{{reconcileDraft.reconciliation_id}}</p><fieldset :disabled="busy||!!reconcileSnapshot"><div class="form-grid"><label>核对原因（至少10字）<textarea v-model="reconcileDraft.reason" minlength="10" maxlength="1000" required/></label><label>服务商账单证据（至少10字）<textarea v-model="reconcileDraft.evidence" minlength="10" maxlength="2000" required/></label><label>实际输入 Token<input v-model.number="reconcileDraft.actual_prompt_tokens" type="number" min="0" max="1000000000" step="1" required/></label><label>实际输出 Token<input v-model.number="reconcileDraft.actual_completion_tokens" type="number" min="0" max="1000000000" step="1" required/></label><label>实际缓存命中 Token<input v-model.number="reconcileDraft.actual_cache_hit_tokens" type="number" min="0" :max="reconcileDraft.actual_prompt_tokens" step="1" required/></label><label>实际费用（原请求币种）<input v-model="reconcileDraft.actual_cost" inputmode="decimal" required/></label></div></fieldset><label class="ai-checkbox"><input v-model="reconcileConsent" type="checkbox" :disabled="busy||!!reconcileSnapshot"/>确认凭证与原请求一致，调整本地账务并保留审计记录；不会再次调用模型</label><p v-if="reconcileUncertain" role="status">上次核对结果未知，原 UUID 和凭证已锁定。</p><el-button native-type="submit" :disabled="busy||!reconcileConsent">{{reconcileUncertain?'使用原 UUID 重试核对':'确认调整账务'}}</el-button><el-button v-if="!reconcileSnapshot" :disabled="busy" @click="reconcileTarget=undefined;reconcileDraft=undefined">取消核对</el-button></form>
   </section>
  </template>
 </div>
</template>
