n-bottom:15px}.ai-text-button{border:0;padding:3px 0;background:none;color:var(--teal);font-size:12px;margin-top:7px}.ai-settings-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:17px}.ai-settings-actions .ai-help{margin:0}.ai-save{display:flex;justify-content:space-between;align-items:center;padding:20px 0;color:var(--muted);font-size:12px}.ai-test,.ai-usage{padding:22px 24px;margin-top:20px}.ai-test h2,.ai-usage h2{font-size:17px;letter-spacing:0}.ai-test .el-button{margin-top:14px}.ai-usage-heading{display:flex;justify-content:space-between;align-items:center}.ai-usage-heading h2{margin:0}.ai-usage>p{font-size:12px;color:var(--muted)}.ai-usage dl{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:20px 0 0}.ai-usage dt{font-size:12px;color:var(--muted)}.ai-usage dd{margin:4px 0 0;font-size:18px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}@media(max-width:760px){.ai-config{padding:0 17px}.ai-test,.ai-usage{padding:18px}.ai-usage dl{grid-template-columns:1fr 1fr}.ai-config .form-grid{gap:16px}.ai-config legend{font-size:16px}}
